module categoryAttachmentProtocolRuntimeLibrary;

@protocol Worker
@required
- (i32) inheritedValue;
+ (i32) classValue;
@end

@protocol Tracer <Worker>
@required
- (i32) tracedValue;
@optional
- (bool) tracedReady;
- (i32) ignoredValue;
@end

@interface Base
- (i32) inheritedValue;
@end

@implementation Base
- (i32) inheritedValue {
  return 7;
}
@end

@interface Widget : Base <Worker>
+ (i32) classValue;
- (i32) tracedValue;
@end

@implementation Widget
+ (i32) classValue {
  return 11;
}
- (i32) tracedValue {
  return 5;
}
@end

@interface Widget (Auxiliary)
- (i32) auxiliaryValue;
@end

@implementation Widget (Auxiliary)
- (i32) auxiliaryValue {
  return 29;
}
@end

@interface Widget (Tracing) <Tracer>
- (i32) tracedValue;
- (bool) tracedReady;
@end

@implementation Widget (Tracing)
- (i32) tracedValue {
  return 13;
}
- (bool) tracedReady {
  return true;
}
@end

@interface Derived : Base <Tracer>
+ (i32) classValue;
- (i32) tracedValue;
- (bool) tracedReady;
@end

@implementation Derived
+ (i32) classValue {
  return 17;
}
- (i32) tracedValue {
  return 19;
}
- (bool) tracedReady {
  return true;
}
@end

@interface Leaf : Derived
@end

@implementation Leaf
@end
